INSERT INTO `san_shop_events` (`id`, `name`, `event_date`, `event_time`, `description`, `description_short`, `picture_url_1`, `picture_url_2`, `picture_url_3`, `show_on_frontpage`, `active`) VALUES
(1,	'LigoWave 6GHz Trådløs Backbone Webinar',	'2015-10-15',	'09:30:00',	'<p>Cloud Router afholder Webinar inden for LigoWave Punkt-til-punkt&nbsp;l&oslash;sninger.</p>\r\n<p>Tidspunkt: Torsdag den 15.&nbsp;oktober&nbsp;2015. kl.09:30 - 10:00</p>\r\n<p>&nbsp;</p>\r\n<p>Send en mail til kontor(@)cloudrouter.dk&nbsp;for at&nbsp;tilmelde.</p>\r\n<p>Du vil efterf&oslash;lgende f&aring; en mail med yderligere information.</p>',	'LigoWave Punkt-til-punkt Webinar - produkt overblik',	'',	'http://www.cloudrouter.dk/docs/pages/LigoWave_Rapidfire.png',	'',	0,	1),
(5,	'LigoWave 6GHz Trådløs backbone Træning',	'2016-01-21',	'09:00:00',	'<p>LigoWave-wireless-professional kursus er passende til dig med TCP/IP netv&aelig;rks erfaring, der er klar til at arbejde selvst&aelig;ndigt med avancerede LigoWave netv&aelig;rksl&oslash;sninger. Du opn&aring;r bl.a. et grundigt WiFi og tr&aring;dl&oslash;s backbone fundament, som kr&aelig;ves af en tr&aring;dl&oslash;s netv&aelig;rks systemingeni&oslash;r.</p>\r\n<p>&nbsp;</p>\r\n<p>Agenda</p>\r\n<p>09:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Overblik inden for radio transmission, 802.11 basis, MIMO og OFDM multi-user.</p>\r\n<p>09:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration af LigoWave Infinity WiFi, multi-segmenter, VLAN og Radius.</p>\r\n<p>11:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Gennemgang af Best-practice inden for high-density WiFi, mobil d&aelig;kning og BYOD.</p>\r\n<p>12:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Frokost, som Cloud Router vil v&aelig;re v&aelig;rt for.</p>\r\n<p>&nbsp;</p>\r\n<p>12:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Overblik inden for TDD duplex og TDMA teknologi.</p>\r\n<p>13:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration af 5GHz DLB punkt-til-punkt WLAN.</p>\r\n<p>14:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration af 5GHz RapidFire professionel PTP WLAN l&oslash;sning.</p>\r\n<p>15:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Gennemgang af Best-practice inden for Wireless backbone for data, voice og CCTV.</p>\r\n<p>16:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Afslutning.</p>',	'LigoWave-wireless-professional kursus er passende til dig med TCP/IP netværks erfaring, der er klar til at arbejde selvstændigt med avancerede LigoWave netværksløsninger.',	'',	'http://www.cloudrouter.dk/docs/LigoWave/LigoWave_training.png',	'',	0,	1),
(12,	'LigoWave WiFi og 6GHz Trådløs Backbone Webinar',	'2016-05-26',	'09:00:00',	'<p>Webinar inden for LigoWave Infinity WiFi og DLB-pro Punkt-til-punkt&nbsp;l&oslash;sninger.</p>\r\n<p>&nbsp;</p>\r\n<p>&bull; Gennemgang af Infinity Access point nyheder</p>\r\n<p>&bull; Gennemgang LigoWave DLB-Pro basestation nyheder</p>\r\n<p>&bull; Gennemgang Infinity Controller platform og muligheder</p>\r\n<p>&bull; Markedsmuligheder for LigoWave Infinity og DLB-pro produkter</p>\r\n<p>&nbsp;</p>\r\n<p>Varighed 25 minutter - online</p>\r\n<p>Link til online presentation: <span style=\"color: #0000ff;\"><a href=\"https://global.gotomeeting.com/join/950118933\"><span style=\"color: #0000ff;\">https://global.gotomeeting.com/join/950118933</span></a></span></p>\r\n<p>&nbsp;</p>\r\n<p>Send en mail til solution(@)cloudrouter.dk for at tilmelde.</p>\r\n<p>Vi vil&nbsp;sende dig en bekr&aelig;ftelse&nbsp;med et password, s&aring; du&nbsp;kan&nbsp;deltage online.</p>',	'Webinar inden for LigoWave Infinity WiFi og DLB-pro Punkt-til-punkt løsninger',	'',	'http://www.cloudrouter.dk/docs/pages/LigoWave_Rapidfire.png',	'',	0,	1),
(13,	'LigoWave 6GHz Trådløs backbone Træning',	'2015-11-17',	'09:00:00',	'<p>LigoWave-wireless-professional kursus er passende til dig med TCP/IP netv&aelig;rks erfaring, der er klar til at arbejde selvst&aelig;ndigt med avancerede LigoWave netv&aelig;rksl&oslash;sninger. Du opn&aring;r bl.a. et grundigt WiFi og tr&aring;dl&oslash;s backbone fundament, som kr&aelig;ves af en tr&aring;dl&oslash;s netv&aelig;rks systemingeni&oslash;r.</p>\r\n<p>&nbsp;</p>\r\n<p>Agenda</p>\r\n<p>09:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Overblik inden for radio transmission, 802.11 basis, MIMO og OFDM multi-user.</p>\r\n<p>09:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration af LigoWave Infinity WiFi, multi-segmenter, VLAN og Radius.</p>\r\n<p>11:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Gennemgang af Best-practice inden for high-density WiFi, mobil d&aelig;kning og BYOD.</p>\r\n<p>12:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Frokost, som Cloud Router vil v&aelig;re v&aelig;rt for.</p>\r\n<p>&nbsp;</p>\r\n<p>12:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Overblik inden for TDD duplex og TDMA teknologi.</p>\r\n<p>13:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration af 5GHz DLB punkt-til-punkt WLAN.</p>\r\n<p>14:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration af 5GHz RapidFire professionel PTP WLAN l&oslash;sning.</p>\r\n<p>15:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Gennemgang af Best-practice inden for Wireless backbone for data, voice og CCTV.</p>\r\n<p>16:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Afslutning.</p>',	'LigoWave-wireless-professional kursus er passende til dig med TCP/IP netværks erfaring, der er klar til at arbejde selvstændigt med avancerede LigoWave netværksløsninger.',	'',	'http://www.cloudrouter.dk/docs/LigoWave/LigoWave_training.png',	'',	0,	1),
(14,	'Mikrotik RouterOS firewall training',	'2016-08-18',	'09:00:00',	'<p>Teoretisk og Hands-on konfigurationer inden for gateway og firewall funktioner p&aring; Mikrotik platform.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Agenda</strong></p>\r\n<p>09:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration Mikrotik OS basis indstillinger</p>\r\n<p>09:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration Source and destination NAT</p>\r\n<p>10:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration Mikrotik som Gateway router</p>\r\n<p>10:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration IP firewall basis filter regler &amp; logging</p>\r\n<p>11:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration Blocking of simple p2p traffic</p>\r\n<p>11:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Hands-on konfiguration Connection tracking &amp;&nbsp;traffic analysis</p>\r\n<p>12:15&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Afslutning og frokost med sandwich med drikkevarer</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Pris: kr. 1.900,- ekskl. moms.</p>\r\n<p>Tilmelding: Du bedes sende en e-mail til <a href=\"mailto:solution@cloudrouter.dk\">solution@cloudrouter.dk</a></p>\r\n<p>Placering: Cloud Router&nbsp;- Virkelyst 20 - 7400 Herning.</p>\r\n<p>&nbsp;</p>\r\n<p>For yderligere information, bedes du venligst kontakte vores kontor.</p>',	'Vi gennemgår teoretisk og Hands-on konfigurationer inden for gateway og firewall funktioner på Mikrotik platform.',	'',	'',	'',	0,	1),
(16,	'LigoWave Infinity WiFi training',	'2016-08-18',	'13:00:00',	'<p>Ops&aelig;tning af Infinity Controller, WiFi netv&aelig;rk, VLAN og Radius konfiguration, med praktiske ops&aelig;tninger p&aring; Infinity Controller platform.</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Agenda</strong></p>\r\n<p>13:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Ops&aelig;tning On-premise Infinity Controller</p>\r\n<p>13:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Tilknytning af Infinity Access points p&aring; Controller</p>\r\n<p>14:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Konfiguration af Network profiles&nbsp;og basic indstillinger</p>\r\n<p>14:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Konfiguration af tr&aring;dl&oslash;st netv&aelig;rk med VLAN og radius</p>\r\n<p>15:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Optimering af netv&aelig;rk&nbsp;for spektrum, roaming m.m.</p>\r\n<p>15:30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Monitorering, fejlfinding og evt. SNMP til eksterne systemer</p>\r\n<p>16:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Afslutning</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>Pris: kr. 1.700,- ekskl. moms.</p>\r\n<p>Tilmelding: Du bedes sende en e-mail til <a href=\"mailto:solution@cloudrouter.dk\">solution@cloudrouter.dk</a></p>\r\n<p>Placering: Cloud Router&nbsp;- Virkelyst 20 - 7400 Herning.</p>\r\n<p>&nbsp;</p>\r\n<p>For yderligere information, bedes du venligst kontakte vores kontor.</p>',	'Opsætning af Infinity Controller, WiFi netværk, VLAN og Radius konfiguration, med praktiske opsætninger på Infinity Controller platform.',	'',	'',	'',	0,	1),
(17,	'802.11 WLAN Træningskursus',	'2016-10-20',	'10:00:00',	'<p>Cloud Routers 802.11 WLAN kursus vil give dig en grundig forst&aring;else for tr&aring;dl&oslash;s datakommunikation. Vi vil p&aring; kurset gennemg&aring; nedenst&aring;ende teoretiske emner, samt eksempler p&aring; praktiske scenarios.</p>\r\n<p><strong><br /></strong><strong>802.11 kommunikation lag</strong><br />&bull;&nbsp;RF spectrum (2.4GHz &amp; 5GHz) <br />&bull;&nbsp;OFDM and QAM modulations<br />&bull;&nbsp;802.11 Media Access Control layer<br />&bull;&nbsp;MIMIO and multiuser MIMIO<br />&bull;&nbsp;802.11n, 802.11ac and Wave 2</p>\r\n<div>&nbsp;</div>\r\n<div><strong>802.11 WiFi netv&aelig;rk</strong><br />&bull;&nbsp;Client association process<br />&bull;&nbsp;CSMA/CA in operation<br />&bull;&nbsp;The hidden node problem<br />&bull;&nbsp;802.11n / ac frame aggregation<br />&bull;&nbsp;802.11ac enhancements<br />&bull;&nbsp;Automatic Power Save Delivery (APSD)<br />&bull;&nbsp;Wireless Quality of service<br />&nbsp;<br /><strong>Radio d&aelig;kning</strong><br />&bull;&nbsp;Antennas, dBi, dBm and EIRP<br />&bull;&nbsp;Receiver sensitivity <br />&bull;&nbsp;Free space coverage and RF obstacles<br />&bull;&nbsp;Radio noise and interference issues<br />&bull;&nbsp;Multipath, 802.11n and ac coverage<br />&bull;&nbsp;Planning radio coverage and capacity</div>\r\n<div>&nbsp;</div>\r\n<div><strong>Tr&aring;dl&oslash;s netv&aelig;rk sikkerhed</strong><br />&bull;&nbsp;WLAN authentication and encryption<br />&bull;&nbsp;WLAN backdoor attacks and prevention<br />&bull;&nbsp;Enterprise wireless security recommendations</div>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Kursuspris</strong>: ekskl. Moms kr. 2.900,-</p>\r\n<p><strong>Sted</strong>: Virkelyst 20 - 7400 Herning</p>\r\n<p><span><strong>Tilmelding</strong>: <a href=\"mailto:solution@cloudrouter.dk\"><span>solution@cloudrouter.dk</span></a></span></p>\r\n<p><span><strong>Tidspunkt:</strong> torsdag den 20. oktober 2016&nbsp;- kl. 10:00 - 15:00</span></p>\r\n<p>&nbsp;</p>\r\n<p>Vi byder velkommen fra kl. 9:30 med morgenkaffe til dem som&nbsp;&oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag.</p>',	'802.11 WLAN kursus giver en grundig forståelse af 802.11 trådløs standard og dele elementer.',	'',	'',	'',	0,	1),
(18,	'LigoWave 6GHz Trådløs Backbone Webinar',	'2016-10-11',	'09:30:00',	'<p>Bliv opdateret inden for markedets mest innovative punkt-til-punkt og multipunkt l&oslash;sninger.</p>\r\n<p>&nbsp;</p>\r\n<p>&bull; Kort overblik af LigoWave punkt-til-punkt l&oslash;sninger</p>\r\n<p>&bull; Markedsmuligheder og kundesegmenter med LigoWave</p>\r\n<p>&nbsp;</p>\r\n<p>Tilmelding: <span style=\"color: #0000ff;\">solution@cloudrouter.dk</span></p>\r\n<p><span style=\"color: #000000;\">Efter tilmeldigen vil du f&aring; et link tilsendt p&aring; din email. <br />Du kan bruge din computer, tablet eller smartphone til at deltage online.</span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>',	'Cloud Router afholder Webinar inden for LigoWave trådløse backbone løsninger',	'',	'',	'http://www.cloudrouter.dk/docs/pages/LigoWave_Rapidfire.png',	0,	1),
(19,	'WLINK IoT Webinar',	'2016-10-11',	'10:00:00',	'<p>V&aelig;r med i WLINK webinar og opdag nye muligheder med WLINK IoT gateways.</p>\r\n<p>&nbsp;</p>\r\n<p>&bull; Kort overblik af WLINK 4G / LTE&nbsp; produkter</p>\r\n<p>&bull; Markedsmuligheder og kundesegmenter med WLINK produkter</p>\r\n<p>&nbsp;</p>\r\n<p>Tilmelding: <span style=\"color: #0000ff;\">solution@cloudrouter.dk</span></p>\r\n<p>Efter tilmeldigen vil du f&aring; et link tilsendt p&aring; din email. <br />Du kan bruge din computer, tablet eller smartphone til at deltage online via internettet.</p>\r\n<p>&nbsp;</p>',	'Cloud Router afholder webinar inden for IgniteNet IoT trådløse løsninger',	'',	'',	'http://www.cloudrouter.dk/docs/events/WLINK.png',	0,	1),
(20,	'LigoWave 6GHz Trådløs Backbone Webinar',	'2016-12-07',	'09:00:00',	'<p><span style=\"color: #333333;\"><span><span><span>Hent eventet som et</span> </span></span><a title=\"Hent LigoWave backbone Webinar som PDF\" href=\"http://www.cloudrouter.dk/docs/events/Webinar_LigoWave_backbone_dec_17.pdf\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">PDF dokument</span></span></a></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">V&aelig;r med online, hvis du har interesse i sidste nyt inden for 4,9 &ndash; 6,1GHz tr&aring;dl&oslash;s backbone. LigoWave tr&aring;dl&oslash;se backbone protokol har evnen til at fungere under selv de mest ekstreme st&oslash;jforhold. N&aring;r du deltager i dette webinar, er du med i konkurrencen om et s&aelig;t DLB 5-15ac bridge. </span><span style=\"color: #333333;\">Fokuspunkter og gennemgang inden for:</span><span style=\"color: #333333;\"><strong><br /></strong></span></p>\r\n<p><span style=\"color: #333333;\"><strong><br /></strong>&bull;&nbsp;LigoPTP RapidFire 4,9 &ndash; 6,1GHz Punkt-til-punkt</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;LigoDLB ac Punkt-til-punkt og Punkt-til-multipunkt</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;iPoll link stabilitet i et st&oslash;jfyldt milj&oslash; vs konkurrenter</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;Installationsmuligheder med tr&aring;dl&oslash;s backbone l&oslash;sning</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\"><strong>Deltag og vind det nye DLB ac 500+ Mbit tr&aring;dl&oslash;st link</strong></span></p>\r\n<p><span style=\"color: #333333;\">N&aring;r du deltager i dette webinar, er du med i konkurrencen om et s&aelig;t DLB 5-15ac bridge</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 30 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via</span> <span style=\"color: #0000ff;\"><a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/598693256410658308\" target=\"_blank\"><span style=\"color: #0000ff;\">GoToWebinar</span></a></span><span style=\"color: #0000ff;\"><br /></span></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>',	'Vær med online, hvis du har interesse i sidste nyt inden for 4,9 – 6,1GHz trådløs backbone. LigoWave trådløse backbone protokol har evnen til at fungere under selv de mest ekstreme støjforhold. Når du deltager i dette webinar, er du med i konkurrencen om et sæt DLB 5-15ac bridge. Klik for at lære mere..',	'',	'http://www.cloudrouter.dk/docs/events/DLB_5-15_ac_link.png',	'http://www.cloudrouter.dk/docs/events/LW_backbone_webinar.png',	0,	1),
(24,	'LigoWave 6GHz backbone Webinar',	'2017-01-10',	'09:00:00',	'<p><span style=\"color: #333333;\"><span><span><span>Hent eventet som et</span> </span></span><a title=\"Hent LigoWave backbone Webinar som PDF\" href=\"http://www.cloudrouter.dk/docs/events/Webinar_LigoWave_backbone_jan_17.pdf\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">PDF dokument</span></span></a></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">V&aelig;r med online, hvis du har interesse i sidste nyt inden for 4,9 &ndash; 6,1GHz tr&aring;dl&oslash;s backbone. LigoWave tr&aring;dl&oslash;se backbone protokol har evnen til at fungere under selv de mest ekstreme st&oslash;jforhold. N&aring;r du deltager i dette webinar, er du med i konkurrencen om et s&aelig;t DLB 5-15ac bridge. </span><span style=\"color: #333333;\">Fokuspunkter og gennemgang inden for:</span><span style=\"color: #333333;\"><strong><br /></strong></span></p>\r\n<p><span style=\"color: #333333;\"><strong><br /></strong>&bull;&nbsp;LigoPTP RapidFire 4,9 &ndash; 6,1GHz Punkt-til-punkt</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;LigoDLB ac Punkt-til-punkt og Punkt-til-multipunkt</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;iPoll link stabilitet i et st&oslash;jfyldt milj&oslash; vs konkurrenter</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;Installationsmuligheder med tr&aring;dl&oslash;s backbone l&oslash;sning</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\"><strong>Deltag og vind det nye DLB ac 500+ Mbit tr&aring;dl&oslash;st link</strong></span></p>\r\n<p><span style=\"color: #333333;\">N&aring;r du deltager i dette webinar, er du med i konkurrencen om et s&aelig;t DLB 5-15ac bridge</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 30 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via</span> <a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/4948670218786299395\" target=\"_blank\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">GoToWebinar</span></span><span style=\"color: #0000ff;\"><br /></span></a></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>',	'Vær med online, hvis du har interesse i sidste nyt inden for 4,9 – 6,1GHz trådløs backbone. LigoWave trådløse backbone protokol har evnen til at fungere under selv de mest ekstreme støjforhold. Når du deltager i dette webinar, er du med i konkurrencen om et sæt DLB 5-15ac bridge. Klik for at lære mere..',	'',	'http://www.cloudrouter.dk/docs/events/DLB_5-15_ac_link.png',	'http://www.cloudrouter.dk/docs/events/LW_backbone_webinar.png',	0,	1),
(26,	'LigoWave 6GHz backbone Webinar',	'2017-08-18',	'09:30:00',	'<p>Deltag i webinar om sidste nyt inden for 4,9 &ndash; 6,1GHz LigoWave tr&aring;dl&oslash;s backbone. LigoWave TDMA baseret tr&aring;dl&oslash;s backbone har evnen til at fungere under selv de mest ekstreme st&oslash;jforhold.</p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><strong><span style=\"color: #333333;\">Presentation fokuspunkter</span></strong></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;LigoDLB ac <span>4,9 &ndash; 6,1GHz&nbsp;</span>Punkt-til-punkt og Punkt-til-multipunkt</span></p>\r\n<p><span style=\"color: #333333;\"><span>&bull;&nbsp;LigoPTP og LigoPTMP 4,9 &ndash; 6,1GHz&nbsp;<span>Punkt-til-punkt og Punkt-til-multipunkt</span></span></span></p>\r\n<p><span style=\"color: #333333;\">&bull; Markedsmuligheder for LigoWave tr&aring;dl&oslash;s backbone l&oslash;sninger</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 25 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via</span> <a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/6386765458857612291\" target=\"_blank\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">GoToWebinar</span></span><span style=\"color: #0000ff;\"><br /></span></a></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>',	'Deltag i webinar om sidste nyt inden for 4,9 – 6,1GHz LigoWave trådløs backbone. LigoWave TDMA baseret trådløs backbone har evnen til at fungere under selv de mest ekstreme støjforhold. Læs videre...',	'',	'',	'http://www.cloudrouter.dk/docs/events/LW_backbone_webinar.png',	0,	1),
(28,	'LigoWave 6GHz backbone Træningskursus',	'2017-03-16',	'09:00:00',	'<p>Tr&aelig;ningen afholdes af LigoWaves egne tr&aelig;nere i samarbejde med Cloud Router. Under tr&aelig;ningen skal du udf&oslash;re hand-on konfigurationer p&aring; k&oslash;reklar RapidFire og DLB hardware enheder, som er velegnet til labs og workshops.&nbsp;Download som<span>&nbsp;</span><span style=\"color: #0000ff;\"><a title=\"LigoWave Wireless backbone Training\" href=\"http://www.cloudrouter.dk/docs/events/LW_Wireless_backbone_training.pdf\" target=\"_blank\"><span style=\"color: #0000ff;\">PDF dokument</span></a>.</span></p>\r\n<p><strong><span style=\"color: #ff6600;\"><br /></span></strong></p>\r\n<p><strong><span style=\"color: #ff6600;\">NB: Alle fremm&oslash;dte vil f&aring; udleveret 1 s&aelig;t LigoWave DLB 5-15ac bridge.</span></strong></p>\r\n<p><span style=\"color: #ff6600;\"><br /></span></p>\r\n<p><strong>Dag 1</strong></p>\r\n<p>08:30 - Velkommen med morgenbr&oslash;d og kaffe<br />09:00 - Introduktion til Punkt-til-punkt tr&aring;dl&oslash;s kommunikation<br />10:00 - RapidFire punkt-til-punkt tr&aring;dl&oslash;st netv&aelig;rk Hand-on lab<br />11:00 - RapidFire VLAN, QoS og bandwidth management Hand-on lab<br />12:00 - Frokost</p>\r\n<p>12:30 - RapidFire&nbsp;management, overv&aring;gning&nbsp;og&nbsp;SNMP Hand-on lab<br />13:30 -&nbsp;Overv&aring;gning og management vha. WNMS platform Hand-on lab<br />14:00 -&nbsp;Gennemgang af LigoWave Installer APP og LinkCalc applikationer<br />15:00 -&nbsp;Kort gennemgang af LigoWave support portal og producent support<br />16:00 -&nbsp;Afslutning</p>\r\n<p><strong><br /></strong></p>\r\n<p><strong>Dag 2</strong><br />08:30 -&nbsp;Velkommen med morgenbr&oslash;d og kaffe<br />09:00 -&nbsp;DLB / DLB ac punkt-til-multipunkt tr&aring;dl&oslash;st netv&aelig;rk Hand-on lab<br />10:00 -&nbsp;DLB / DLB ac VLAN, QoS and bandwidth management Hand-on lab<br />11:00 - DLB / DLB ac&nbsp;management, overv&aring;gning og&nbsp;SNMP Hand-on lab</p>\r\n<p>12:00 -&nbsp;Frokost</p>\r\n<p>12:30 -&nbsp;LigoDLB og LigoPTP eksamen for producent certificering<br />13:30 -&nbsp;Best practice ops&aelig;tninger inden for tr&aring;dl&oslash;s backbone for CCTV<br />14:00 -&nbsp;Best practice ops&aelig;tninger inden for tr&aring;dl&oslash;s internetudbyder l&oslash;sninger<br />14:30 -&nbsp;Kort foredrag af en erfaren CCTV installat&oslash;r fra Danmark<br />15:00 -&nbsp;Kort foredrag af en erfaren tr&aring;dl&oslash;s internetudbyder fra Danmark<br />15:30 -&nbsp;Afslutning</p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>\r\n<p><strong>Information</strong><br />Du skal medbringe en Laptop computer med Ethernet indgang, WiFi, og Chrome eller Firefox.<br />Du skal have basisniveau erfaring inden for IP netv&aelig;rk, Ethernet og WiFi kommunikation.<br />Der vil v&aelig;re 3 x 230v str&oslash;mstik, 1 x Ethernet og WiFi netv&aelig;rksadgang pr. deltager i lokalet.</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\"><strong>Pris</strong>: ekskl. Moms kr. 3.900,-</span></p>\r\n<p><strong><span><span style=\"color: #333333;\"><strong>Tilmelding</strong></span>: <a href=\"mailto:solution@cloudrouter.dk\"><span>solution@cloudrouter.dk</span></a></span></strong></p>\r\n<p><strong><br /></strong></p>\r\n<p><span style=\"color: #333333;\"><strong>Sted</strong>: Svendborgvej 226, 5260 Odense S</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Tidspunkt:</strong>&nbsp;Fra torsdag den 16. marts, kl. 09:00 - f<span>redag den 17. marts 2017 kl. 15:30</span></span></p>\r\n<p>&nbsp;</p>\r\n<p>Vi byder velkommen fra kl. 08:30 med morgenkaffe og rundstykker til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag. For yderligere information, bedes du venligst kontakte os.</p>',	'LigoWave Trådløs backbone træning består af 2 dages hands-on træning inden for DLB-ac og LigoPTP RapidFire punkt-til-punkt og multipunkt løsninger. Klik for at læse mere..',	'http://www.cloudrouter.dk/docs/events/LW_training.png',	'http://www.cloudrouter.dk/docs/events/PTMP_tower.jpg',	'',	0,	1),
(29,	'Mikrotik RouterOS Webinar',	'2017-08-22',	'09:00:00',	'<p>V&aelig;r med i en sp&aelig;ndende webinar af verdens mest effektive router platform, inden for Routing, VPN, MPLS, bandwidth-management og hotspot-authentication.</p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">Fokuspunkter og gennemgang inden for:</span></p>\r\n<p><span style=\"color: #333333;\"><strong><br /></strong>&bull;&nbsp;Mikrotik router og switch enheder</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Mikrotik RouterOS netv&aelig;rksf<span>unktioner</span></span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;Kunder og&nbsp;markedssegmenter for Mikrotik produkter</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Kort gennemgang af Mikrotik tr&aelig;ning og certificering</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 25 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via</span> <a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/461768876144935427\" target=\"_blank\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">GoToWebinar</span></span><span style=\"color: #0000ff;\"><br /></span></a></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>',	'Vær med i en spændende webinar om verdens mest effektive router platform, inden for Routing, VPN, MPLS, bandwidth-management og hotspot-authentication. Læs videre...',	'',	'http://www.cloudrouter.dk/docs/events/Mikrotik_routerOS.jpg',	'http://www.cloudrouter.dk/docs/events/Mikrotik_CCR.jpg',	0,	1),
(30,	'LigoWave Infinity WiFi Webinar',	'2017-08-18',	'09:00:00',	'<p style=\"text-align: justify;\">Deltag i webinar om en h&oslash;jtydende WiFi l&oslash;sning. Infinity WiFi har en effektiv d&aelig;kning og utrolig h&oslash;j dataoverf&oslash;rsel til h&aring;ndholdte enheder med Stand-alone, In-AP samt Cloud controller management muligheder.</p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #333333;\"><br /></span></p>\r\n<p><strong><span style=\"color: #333333;\">Fokuspunkter og gennemgang inden for:</span></strong></p>\r\n<p><span style=\"color: #333333;\"><strong><br /></strong>&bull;&nbsp;Infinity WiFi hardware enheder</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;<span>Infinity WiFi management og&nbsp;<span>funktioner</span></span></span></p>\r\n<p><span style=\"color: #333333;\">&bull; Markedet for&nbsp;</span><span style=\"color: #333333;\">Infinity WiFi l&oslash;sning</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 25 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via</span> <a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/5566924509211141891\" target=\"_blank\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">GoToWebinar</span></span><span style=\"color: #0000ff;\"><br /></span></a></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>',	'Deltag i webinar om en højtydende WiFi løsning med Stand-alone, In-AP og Cloud controller management muligheder. Infinity WiFi har en effektiv dækning og utrolig høj dataoverførsel til håndholdte enheder. Læs videre...',	'',	'http://www.cloudrouter.dk/docs/events/infinity_topology.png',	'',	0,	1),
(31,	'Mikrotik RouterOS Webinar',	'2017-10-17',	'09:00:00',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">V&aelig;r med i en sp&aelig;ndende webinar inden for den mest effektive router platform, til Routing, VPN, MPLS, bandwidth-management og hotspot-authentication m.m.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\"><strong>Fokuspunkter</strong>:</span></p>\r\n<p><span style=\"color: #000000;\"><strong><br /></strong>&bull;&nbsp;Mikrotik router og switch hardware</span></p>\r\n<p><span style=\"color: #000000;\">&bull; Mikrotik RouterOS netv&aelig;rksfunktioner</span></p>\r\n<p><span style=\"color: #000000;\">&bull; Markedssegmenter og kunder for Mikrotik produkter</span></p>\r\n<p><span style=\"color: #000000;\">&bull; Kort gennemgang af Mikrotik tr&aelig;ning og certificering</span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\">Varighed: 25 minutter</span></p>\r\n<p><span style=\"color: #000000;\">Tilmeld dig online via&nbsp;</span><span style=\"color: #0000ff;\"><a title=\"Tilmeld online via GoToWebinar\" href=\"https://register.gotowebinar.com/register/171912327037222402\" target=\"_blank\"><span style=\"color: #0000ff;\">GoToWebinar</span></a></span></p>\r\n<p><span><span><br /></span></span></p>',	'Vær med i en spændende webinar inden for den mest effektive router platform, til Routing, VPN, MPLS, bandwidth-management og hotspot-authentication m.m. Læs videre...',	'',	'http://www.cloudrouter.dk/docs/events/Mikrotik_routerOS.jpg',	'http://www.cloudrouter.dk/docs/events/Mikrotik_CCR.jpg',	0,	0),
(32,	'LigoWave 6GHz backbone Webinar',	'2017-10-17',	'09:30:00',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Deltag i webinaret om sidste nyt inden for LigoWave 4,9 &ndash; 6,1GHz&nbsp;tr&aring;dl&oslash;s backbone. LigoWave TDMA baseret tr&aring;dl&oslash;s backbone har evnen til at fungere under selv de mest ekstreme st&oslash;jforhold.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\"><strong>Online presentation og seneste nyt inden for:<br /><br /></strong></span></p>\r\n<p><span style=\"color: #000000;\">&bull;&nbsp;LigoDLB ac, den mest attraktive Punkt-til-punkt og multipunkt l&oslash;sning&nbsp;p&aring; markedet.</span></p>\r\n<p><span style=\"color: #000000;\">&bull;&nbsp;LigoPTP RapidFire tr&aring;dl&oslash;s bridge&nbsp;l&oslash;sning&nbsp;til&nbsp;professionelle Punkt-til-punkt&nbsp;installationer.</span></p>\r\n<p><span style=\"color: #000000;\">&bull; LigoPTMP&nbsp;Carrier grade&nbsp;Punkt-til-multipunkt til&nbsp;professionelle CCTV og&nbsp;WTTx&nbsp;installationer.</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\">Varighed: 30 minutter</span></p>\r\n<p><span style=\"color: #000000;\">Tilmeld dig online via&nbsp;</span><span style=\"color: #0000ff;\"><a title=\"Tilmeld online via GoToWebinar\" href=\"https://register.gotowebinar.com/register/2352358234126368514\" target=\"_blank\"><span style=\"color: #0000ff;\">GoToWebinar</span></a></span></p>\r\n<p><span><br /></span></p>',	'Deltag i webinaret om sidste nyt inden for LigoWave 4,9 – 6,1GHz trådløs backbone. LigoWave TDMA baseret trådløs backbone har evnen til at fungere under selv de mest ekstreme støjforhold. Læs videre...',	'',	'',	'http://www.cloudrouter.dk/docs/events/LW_backbone_webinar.png',	0,	1),
(34,	'Mikrotik RouterOS Træningskursus',	'2017-11-28',	'09:00:00',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Cloud Routers Mikrotik training best&aring;r af teoretisk gennemgang og Hands-on konfigurationer inden for gateway, firewall, QoS, b&aring;ndbreddestyring og Hotspot funktioner p&aring; Mikrotik platform.&nbsp;</span><a title=\"Klik p&aring; at hente som et PDF dokument\" href=\"http://www.cloudrouter.dk/docs/events/2017/Mikrotik_RouterOS_training.pdf\" target=\"_blank\"><span style=\"color: #0000ff;\">Hent <span><strong><span>PDF</span></strong></span></span></a></p>\r\n<p><span style=\"color: #ff6600;\"><strong><br /></strong></span></p>\r\n<p><span style=\"color: #ff6600;\"><strong>NB: Alle fremm&oslash;dte vil f&aring; udleveret 1 stk. MikroTik hAP ac router&nbsp;RB962UiGS-5HacT2HnT.</strong></span></p>\r\n<div>&nbsp;</div>\r\n<p><span style=\"color: #000000;\"><strong>Agenda</strong></span></p>\r\n<p><span style=\"color: #000000;\">08:30&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Velkommen med morgenbr&oslash;d og kaffe</span></p>\r\n<p><span style=\"color: #000000;\">09:00 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;Introduktion til Mikrotik router, switch og RouterOS platform</span></p>\r\n<p><span style=\"color: #000000;\">09:30 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ops&aelig;tning af RouterOS System basis, interface og IP indstillinger</span></p>\r\n<p><span style=\"color: #000000;\">10:00 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ops&aelig;tning af network services DHCP, DNS, NTP, m.m.</span></p>\r\n<p><span style=\"color: #000000;\">10:30 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ops&aelig;tning af Internet gateway, SNAT &amp; DNAT funktioner</span></p>\r\n<p><span style=\"color: #000000;\">11:00 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ops&aelig;tning af IP filter basis, firewall regler, connections states&nbsp;&amp; logging</span></p>\r\n<p><span style=\"color: #000000;\">12:00 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Best practice firewall regler for&nbsp;p2p traffik, DDoS attack og DNS protection</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\">12:30 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Frokost</span></p>\r\n<p><span style=\"color: #000000;\">13:00&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Gennemgang af connection tracking &amp;&nbsp;traffic analysis</span></p>\r\n<p><span style=\"color: #000000;\">13:30 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ops&aelig;tning af QoS,&nbsp;traffic shaping, bandwidth control &amp; load balancing</span></p>\r\n<p><span style=\"color: #000000;\">15:00 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ops&aelig;tning af NAS / Hotspot authentication vha. ekstern radius server</span></p>\r\n<p><span style=\"color: #000000;\">16:00 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Afslutning</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\"><strong>Pris:</strong> kr. 3.500,- ekskl. moms.</span></p>\r\n<p><span style=\"color: #000000;\"><strong>Tilmelding:</strong>&nbsp;<span style=\"color: #0000ff;\"><a href=\"mailto:solution@cloudrouter.dk\"><span style=\"color: #0000ff;\">salg@cloudrouter.dk</span></a></span></span></p>\r\n<p><span style=\"color: #000000;\"><strong>Placering:</strong>&nbsp;Svendborgvej 226, 5260 Odense S</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\">Vi byder velkommen fra kl. 08:30 med morgenkaffe og rundstykker&nbsp;til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag. For yderligere information, bedes du venligst kontakte vores kontor.</span></p>\r\n<p>&nbsp;</p>',	'Cloud Routers Mikrotik training består af teoretisk gennemgang og Hands-on konfigurationer inden for gateway, firewall båndbreddestyring og QoS funktioner på Mikrotik platform. Klik for at læse mere..',	'',	'http://www.cloudrouter.dk/docs/events/Mikrotik_routerOS.jpg',	'http://www.cloudrouter.dk/docs/events/Mikrotik_training.png',	0,	0),
(35,	'Ceragon advanced training for IP-20 fuld-dupleks radiolinks',	'2018-05-02',	'09:00:00',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Ceragon IP-20 platform&nbsp;advanced training afholdes af Ceragons egen systemingeni&oslash;r.</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #000000;\"><a title=\"Ceragon certification training course\" href=\"https://drive.google.com/open?id=1v9WtJZtA7kliJXddeCAVePwqkdpPkN89\" target=\"_blank\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">Download PDF</span></span></a></span></p>\r\n<p>&nbsp;</p>\r\n<table border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td>\r\n<p><span style=\"color: #000000;\"><strong>Tidspunkt</strong></span></p>\r\n</td>\r\n<td><span style=\"color: #000000;\"><strong>Dag 1 -&nbsp;<span>onsdag den 02. maj 2018</span></strong></span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">09:00 &ndash; 10:00 &nbsp; &nbsp;&nbsp;</span></td>\r\n<td><span style=\"color: #000000;\">IP-20 Product Overview &nbsp; &nbsp; &nbsp; &nbsp;</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">10:00 &ndash; 10:15</span></td>\r\n<td><span style=\"color: #000000;\">Coffee Break</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">10:15 &ndash; 12:00</span></td>\r\n<td><span style=\"color: #000000;\">IP-20 C/E Housing and System Configurations &nbsp;</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">12:00 &ndash; 12:30</span></td>\r\n<td><span style=\"color: #000000;\">Lunch Break&nbsp;</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">12:30 &ndash; 13:30</span></td>\r\n<td><span style=\"color: #000000;\">IP-20 C/E Installation</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">13:30 - 13:45</span></td>\r\n<td><span style=\"color: #000000;\">Coffee Break</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">13:45 - 14:45</span></td>\r\n<td><span style=\"color: #000000;\">First Login &amp; Link Parameter</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">14:45 - 15:00</span></td>\r\n<td><span style=\"color: #000000;\">Coffee Break</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">15:00 - 16:00</span></td>\r\n<td><span style=\"color: #000000;\">First Login &amp; Link Parameter</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<table border=\"0\">\r\n<tbody>\r\n<tr>\r\n<td><span style=\"color: #000000;\"><strong>Tidspunkt</strong></span></td>\r\n<td>\r\n<p><span style=\"color: #000000;\"><strong>Dag 2 -&nbsp;<span>torsdag den 03. maj 2018</span></strong></span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">09:00 &ndash; 10:00 &nbsp; &nbsp;&nbsp;</span></td>\r\n<td>\r\n<p><span style=\"color: #000000;\">ACM + MSE + ABC + XPIC</span></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">10:00 &ndash; 10:15</span></td>\r\n<td><span style=\"color: #000000;\">Coffee Break</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">10:15 &ndash; 12:00</span></td>\r\n<td><span style=\"color: #000000;\">Carrier Ethernet Switch &ndash; Pipe InBand MNG</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">12:00 &ndash; 12:30</span></td>\r\n<td><span style=\"color: #000000;\">Lunch Break&nbsp;</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">12:30 &ndash; 13:30</span></td>\r\n<td><span style=\"color: #000000;\">Carrier Ethernet Switch, Pipe InBand MNG</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">13:30 - 13:45</span></td>\r\n<td><span style=\"color: #000000;\">Coffee Break</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">13:45 - 14:45</span></td>\r\n<td><span style=\"color: #000000;\">Troubleshooting</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">14:45 - 15:00</span></td>\r\n<td><span style=\"color: #000000;\">Coffee Break</span></td>\r\n</tr>\r\n<tr>\r\n<td><span style=\"color: #000000;\">15:00 - 16:00</span></td>\r\n<td><span style=\"color: #000000;\">Backup and Restore + Software Upgrade and Downgrade</span></td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<p><span style=\"color: #000000;\">&nbsp;</span></p>\r\n<p><span style=\"color: #000000;\"><strong>Pris:</strong> ekskl. Moms kr. 8.900,-</span></p>\r\n<p><span style=\"color: #000000;\"><strong>Tilmelding:</strong> <span style=\"color: #0000ff;\"><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #0000ff;\">salg@cloudrouter.dk</span></a></span></span></p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: justify;\"><span style=\"text-align: justify;\"><span style=\"color: #333333;\">Vi byder velkommen fra kl. 08:30 med morgenkaffe og rundstykker til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag.</span></span><span style=\"color: #333333;\"><br /></span></p>',	'Ceragon IP-20 platform advanced training afholdes af Ceragons egen systemingeniør.',	'http://www.cloudrouter.dk/docs/events/2017/Backhaul_city.png',	'',	'',	0,	0),
(37,	'802.11 WLAN kommunikation kursus',	'2018-03-22',	'09:00:00',	'<p style=\"text-align: justify;\"><span style=\"color: #000000;\">Cloud Routers 802.11 WLAN-kursus giver en grundig forst&aring;else af tr&aring;dl&oslash;s datakommunikation. <br />Vi vil under kurset gennemg&aring; nedenst&aring;ende emner, sammen med nogle praktiske scenarios.&nbsp;</span></p>\r\n<p style=\"text-align: justify;\"><span style=\"color: #0000ff;\"><a title=\"WLAN kommunikation kursus\" href=\"https://drive.google.com/open?id=1a01U9pP_9PdgvkJnK_X1WF64tEX4zRo8\" target=\"_blank\"><span style=\"color: #0000ff;\">Download PDF</span></a></span></p>\r\n<div>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\"><strong>802.11 kommunikation lag</strong></span><br /><span style=\"color: #333333;\">&bull; RF spectrum (2.4GHz &amp; 5GHz) </span><br /><span style=\"color: #333333;\">&bull; QAM &amp; OFDM modulations</span><br /><span style=\"color: #333333;\">&bull; 802.11 Media Access Control layer</span><br /><span style=\"color: #333333;\">&bull; MIMIO &amp; multiuser MIMIO</span><br /><span style=\"color: #333333;\">&bull; 802.11n, 802.11ac, Wave 2 &amp; 802.11ax</span></p>\r\n<p><span style=\"color: #333333;\"><strong><br />802.11 WiFi netv&aelig;rk </strong></span><br /><span style=\"color: #333333;\">&bull; Client association process</span><br /><span style=\"color: #333333;\">&bull; CSMA/CA in operation</span><br /><span style=\"color: #333333;\">&bull; The hidden node problem</span><br /><span style=\"color: #333333;\">&bull; 802.11n / ac / 802.11ax frame aggregation</span><br /><span style=\"color: #333333;\">&bull; 802.11ac &amp; 802.11ax enhancements</span><br /><span style=\"color: #333333;\">&bull; Automatic Power Saving</span><br /><span style=\"color: #333333;\">&bull; Wireless Quality of service</span><br /> <br /><span style=\"color: #333333;\"><strong>Radio d&aelig;kning</strong></span><br /><span style=\"color: #333333;\">&bull; Antennas, dBi, dBm &amp; EIRP</span><br /><span style=\"color: #333333;\">&bull; Receiver sensitivity </span><br /><span style=\"color: #333333;\">&bull; Free space coverage &amp; RF obstacles</span><br /><span style=\"color: #333333;\">&bull; Radio noise &amp; interference issues</span><br /><span style=\"color: #333333;\">&bull; Multipath, 802.11n / ac / ax coverage</span><br /><span style=\"color: #333333;\">&bull; Planning radio coverage &amp; capacity</span><br /> <br /><span style=\"color: #333333;\"><strong>Tr&aring;dl&oslash;s netv&aelig;rk sikkerhed</strong></span><br /><span style=\"color: #333333;\">&bull; WLAN authentication &amp; encryption</span><br /><span style=\"color: #333333;\">&bull; WLAN backdoor attacks &amp; prevention</span><br /><span style=\"color: #333333;\">&bull; Enterprise wireless security</span></p>\r\n</div>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Pris:</strong> ekskl. Moms kr. 4.600,-</span></p>\r\n<p><strong><span><span style=\"color: #000000;\"><strong>Tilmelding</strong>:</span> </span></strong><span style=\"color: #0000ff;\"><a href=\"mailto:solution@cloudrouter.dk\"><span style=\"color: #0000ff;\">salg@cloudrouter.dk</span></a></span></p>\r\n<p><span style=\"color: #333333;\"><strong><strong>Tidspunkt:</strong></strong>&nbsp;kl. 09:00 - 15.30&nbsp;</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #ff0000;\"><strong>NB: Alle fremm&oslash;dte vil f&aring; udleveret 1 stk. LigoWave NFT-2ac Access point.</strong></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\">Vi byder velkommen fra kl. 08:30 med morgenkaffe og rundstykker til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag.</span></p>',	'Cloud Routers 802.11 WLAN-kursus giver en grundig forståelse af trådløs datakommunikation. \r\nVi vil under kurset gennemgå nedenstående teoretiske emner, sammen med nogle praktiske scenarios.',	'',	'http://www.cloudrouter.dk/docs/events/WLAN_kursus.png',	'',	0,	1),
(39,	'LigoWave DLB-ac og LigoPTMP Hands-on labs',	'2018-01-17',	'09:00:00',	'<p><span style=\"color: #000000;\">Under tr&aelig;ningen skal du udf&oslash;re hand-on konfigurationer p&aring; k&oslash;reklar LigoDLB-ac og LigoPTMP&nbsp;hardware enheder. Download</span> <span style=\"color: #0000ff;\"><a title=\"LigoWave Wireless backbone Hand-on Training\" href=\"https://drive.google.com/open?id=0B4vSMcqTmm9sVk44dHp2dmdJMU0\" target=\"_blank\"><span style=\"color: #0000ff;\">PDF dokument</span></a>.</span></p>\r\n<p><strong><span style=\"color: #ff6600;\"><br /></span></strong></p>\r\n<p><strong><span style=\"color: #ff6600;\">NB: Alle fremm&oslash;dte vil f&aring; udleveret 1 s&aelig;t LigoWave DLB 5-15ac bridge.</span></strong></p>\r\n<p><span style=\"color: #ff6600;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\">08:30 - Morgenbr&oslash;d og kaffe</span><br /><span style=\"color: #000000;\">09:00 - Introduktion til Punkt-til-punkt / multipunkt tr&aring;dl&oslash;s kommunikation</span><br /><span style=\"color: #000000;\">09:30 - DLB ac punkt-til-multipunkt tr&aring;dl&oslash;st netv&aelig;rk Hand-on lab</span><br /><span style=\"color: #000000;\">10:30 - DLB ac VLAN, QoS and bandwidth management Hand-on lab</span><br /><span style=\"color: #000000;\">11:15 - DLB ac&nbsp;management og SNMP overv&aring;gning Hand-on lab</span></p>\r\n<p><span style=\"color: #000000;\">12:00 -&nbsp;Frokost</span></p>\r\n<p><span style=\"color: #000000;\">12:30 - LigoPTMP punkt-til-multipunkt tr&aring;dl&oslash;st backbone Hand-on lab</span></p>\r\n<p><span style=\"color: #000000;\">13:30 - LigoPTMP&nbsp;VLAN, QoS og bandwidth management Hand-on lab</span><br /><span style=\"color: #000000;\">14:15 -&nbsp;LigoPTMP&nbsp;management og SNMP overv&aring;gning&nbsp;Hand-on lab</span><br /><span style=\"color: #000000;\">15:00 -&nbsp;Gennemgang af WNMS, LinkCalc applikation og&nbsp;LigoWave support portal</span><br /><span style=\"color: #000000;\">15:45 - Tr&aring;dl&oslash;s backbone Best practice ops&aelig;tninger for CCTV, WiFi og internet </span><br /><span style=\"color: #000000;\">16:30 -&nbsp;Afslutning</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><strong>Information</strong></span><br /><span style=\"color: #000000;\">Du skal medbringe en Laptop computer med Ethernet indgang, WiFi, og Chrome eller Firefox.</span><br /><span style=\"color: #000000;\">Du skal have basisniveau erfaring inden for IP netv&aelig;rk, Ethernet og WiFi kommunikation.</span><br /><span style=\"color: #000000;\">Der vil v&aelig;re 2 x 230v str&oslash;mstik, 1 x Ethernet og WiFi netv&aelig;rksadgang pr. deltager i lokalet.</span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #000000;\"><strong>Slutkunde pris:&nbsp;</strong>ekskl. Moms kr. 4.200,-</span></p>\r\n<p><strong><span><span style=\"color: #000000;\"><strong>Tilmelding</strong>:</span> <span style=\"color: #0000ff;\"><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #0000ff;\">salg@cloudrouter.dk</span></a></span></span></strong></p>\r\n<p><strong><br /></strong></p>\r\n<p><span style=\"color: #000000;\"><strong>Sted</strong>: Svendborgvej 226, 5260 Odense S</span></p>\r\n<p><span style=\"color: #000000;\"><strong>Tidspunkt:</strong>&nbsp;Onsdag den 17. januar 2018 kl. 09:00 - 16:30</span></p>\r\n<p><span style=\"color: #000000;\"><br /></span></p>\r\n<p><span style=\"color: #000000;\">Vi byder velkommen fra kl. 08:30 med morgenkaffe og rundstykker til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag. For yderligere information, bedes du venligst kontakte os.</span></p>',	'Under træningen skal du udføre hand-on konfigurationer på køreklar DLB-ac og LigoPTMP hardware enheder. Klik for at læse mere..',	'http://www.cloudrouter.dk/docs/events/LW_training.png',	'http://www.cloudrouter.dk/docs/events/PTMP_tower.jpg',	'',	0,	0),
(40,	'Administrerbar WiFi til antenne- og boligforeninger - Webinar',	'2018-03-07',	'09:00:00',	'<p><span style=\"color: #333333;\">Deltag i 25 minutters webinar om, hvordan vores administrerbar WiFi til antenne- og boligforeninger, l&oslash;ser de udfordringer der er p&aring; et WiFi netv&aelig;rk i private hjem.</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;LigoWave WiFi Access punkter&nbsp;og funktioner</span></p>\r\n<p><span style=\"color: #333333;\">&bull; D&aelig;kning, hastighed og stabilitet p&aring;&nbsp;<span>LigoWave&nbsp;WiFi</span></span></p>\r\n<p><span style=\"color: #333333;\">&bull; LigoWave&nbsp;Access punkter&nbsp;<span>administration via&nbsp;<span>Panther-Admin</span>&nbsp;</span></span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 25 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via</span> <a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/2170184553764784643\" target=\"_blank\"><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\">GoToWebinar</span></span><span style=\"color: #0000ff;\"><br /></span></a></p>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>',	'Deltag i 25 minutters webinar om, hvordan vores administrerbar WiFi til antenne- og boligforeninger, løser de udfordringer der er på et WiFi netværk i private hjem.',	'',	'http://www.cloudrouter.dk/docs/events/2018/Home_WiFi.png',	'http://www.cloudrouter.dk/docs/events/2018/Panther-admin-WiFi.png',	0,	1),
(41,	'Multi-punkt trådløs backbone for WiFi, CCTV og Internet - Webinar',	'2018-02-27',	'08:30:00',	'<p><span style=\"color: #333333;\">Hvordan anvendes et TDD-dupleks <span>tr&aring;dl&oslash;s&nbsp;</span>Punkt-til-multipunkt p&aring; 3GHz, 5GHz eller 6GHz, som backbone for udend&oslash;rs WiFi installationer, CCTV kamera og internet tilslutninger (husstande, tekniske bygninger og IoT apparater)?</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;5GHz licensfri Punkt-til-multipunkt&nbsp;netv&aelig;rk</span></p>\r\n<p><span style=\"color: #333333;\">&bull; 3 &amp; 6GHz licenserede&nbsp;Punkt-til-multipunkt&nbsp;netv&aelig;rk</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Eksisterende installationer for Punkt-til-multipunkt l&oslash;sninger</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 25 minutter</span><br /><span style=\"color: #333333;\">Tilmeld dig online via&nbsp;</span><a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/8892085174057115651\" target=\"_blank\"><span style=\"color: #0000ff;\">GoToWebinar</span></a></p>\r\n<p><span style=\"color: #0000ff;\"><br /></span></p>',	'Hvordan anvendes et trådløs Punkt-til-multipunkt på 3GHz, 5GHz eller 6GHz, som backbone for udendørs WiFi installationer, CCTV kamera og internet tilslutninger (husstande, tekniske bygninger og IoT apparater)?',	' http://www.cloudrouter.dk/docs/events/2018/Indsutri_link.png',	'http://www.cloudrouter.dk/docs/events/2018/Outdoor_lamp_cctv.png',	' http://www.cloudrouter.dk/docs/events/2018/LigoPTMP_CCTV.png',	0,	1),
(42,	'Kan fuld-dupleks Radiolinks supplere fibergravninger - Webinar',	'2018-02-27',	'09:00:00',	'<p><span style=\"color: #333333;\">Hvordan supplerer en fuld-dupleks radiolink p&aring; 7, 10, 15, 18, 23 eller 80GHz en fibergravning?</span></p>\r\n<p><span style=\"color: #333333;\">Kan et fuld-dupleks radiolink levere fiber-lignende hastigheder og responstider?</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;Hvad er kapacitet og latency p&aring; et Full-duplex radiolink</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Hvilke afstande og oppetid kan der opn&aring;s p&aring; Full-duplex&nbsp;radiolinks</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Anvendelsesmuligheder og kundesegmener for&nbsp;Full-duplex&nbsp;radiolinks</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 25 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via&nbsp;</span><span style=\"color: #0000ff;\"><a title=\"Tilmeld online via GoToWebinar\" href=\"https://attendee.gotowebinar.com/register/902464139613564419\" target=\"_blank\"><span style=\"color: #0000ff;\">GoToWebinar</span></a></span></p>\r\n<p><span style=\"color: #0000ff;\"><span style=\"color: #0000ff;\"><br /></span></span></p>',	'Hvordan supplerer en fuld-dupleks radiolink på 7, 10, 15, 18, 23 eller 80GHz en fibergravning? Kan et fuld-dupleks radiolink levere fiber-lignende hastigheder og responstider?',	'http://www.cloudrouter.dk/docs/events/2018/Ceragon_backhaul.png',	'http://www.cloudrouter.dk/docs/events/2018/Ceragon_80GHz_backhaul_site-b.png',	'http://www.cloudrouter.dk/docs/events/2018/Ceragon_80GHz_backhaul.png',	0,	1),
(43,	'Højtydende WiFi løsning til virksomheder - Webinar',	'2018-03-07',	'08:30:00',	'<p><span style=\"color: #333333;\">Hvad skal der til for at implementere et stabilt og h&oslash;jtydende WiFi netv&aelig;rk, hos virksomheder, skoler og p&aring; offentlige lokationer?</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">&bull; Ydeevne p&aring;&nbsp;Infinity WiFi Access punkter</span></p>\r\n<p><span style=\"color: #333333;\">&bull;&nbsp;D&aelig;kning og stabilitet p&aring;&nbsp;Infinity WiFi Access punkter</span></p>\r\n<p><span style=\"color: #333333;\">&bull; K<span>undesegmenter og l<span>&oslash;sningsmuligheder </span></span>for Infinity&nbsp;WiFi</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">Varighed: 25 minutter</span></p>\r\n<p><span style=\"color: #333333;\">Tilmeld dig online via <a title=\"Online registration for Cloud Routers Webinar\" href=\"https://attendee.gotowebinar.com/register/4598352629615004931\" target=\"_blank\"><span style=\"color: #0000ff;\">GoToWebinar</span></a></span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>',	'Hvad skal der til for at implementere et stabilt og højtydende WiFi netværk, hos virksomheder, skoler og på offentlige lokationer?',	'http://www.cloudrouter.dk/docs/events/2018/Enterprise_WiFi.png',	'http://www.cloudrouter.dk/docs/events/2018/Smart_city_lamp_WiFi.png',	'http://www.cloudrouter.dk/docs/events/2018/Outdoor_sector_WiFi.png',	0,	1),
(44,	'LigoWave WiFi via Panther-admin hands-on workshop',	'2018-04-24',	'08:30:00',	'<p>LigoWave Infinity WiFi&nbsp;administration og vedligeholdelse, via Panther-admin system.</p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\">Agenda - opdateres den&nbsp;24. marts 2018</span></p>\r\n<p><span style=\"color: #333333;\"><br /></span></p>',	'LigoWave Infinity WiFi administration og vedligeholdelse, via Panther-admin system.',	'',	'',	'',	0,	0),
(45,	'LigoWave Cloud managed Infinity WiFi hands-on workshop',	'2018-04-26',	'08:30:00',	'<p><span style=\"color: #333333;\">Under tr&aelig;ningen skal du udf&oslash;re hand-on konfigurationer p&aring; k&oslash;reklar Infinity controller og Access punkter.&nbsp;</span><a title=\"LigoWave Infinity WiFi hands-on workshop\" href=\"https://drive.google.com/open?id=1R42E0tiTKTKC2sR7mhtHtdIVzQzaDcNi\" target=\"_blank\"><span style=\"color: #0000ff;\">Download PDF</span></a></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">08:00 - Morgenbr&oslash;d</span><br /><span style=\"color: #333333;\">08:30 - Introduktion til 802.11 WiFi tr&aring;dl&oslash;s kommunikation</span><br /><span style=\"color: #333333;\">09:00 - Infinity WiFi Stand-alone / Master-AP konfiguration</span><br /><span style=\"color: #333333;\">10:00 - Infinity Cloud management VmWare ops&aelig;tning</span><br /><span style=\"color: #333333;\">10:30 - Infinity Cloud management basis konfiguration</span><br /><span style=\"color: #333333;\">11:00 - Infinity Cloud management advanced konfiguration</span></p>\r\n<p><span style=\"color: #333333;\">12:00 - Frokost</span></p>\r\n<p><span style=\"color: #333333;\">12:30 - Infinity Cloud management VLAN-segmenter og WPA-2 enterprise konfiguration</span><br /><span style=\"color: #333333;\">13:30 - Infinity Cloud management Hotspot netv&aelig;rk, radius og login-portal konfiguration</span><br /><span style=\"color: #333333;\">14:30 - Infinity Cloud management Mesh netv&aelig;rk konfiguration</span><br /><span style=\"color: #333333;\">15:00 - Infinity Cloud management QoS, bandwidth og maps konfiguration</span><br /><span style=\"color: #333333;\">15:30 - Infinity Cloud managed WiFi Best-practice konfiguration</span><br /><span style=\"color: #333333;\">16:00 &ndash; Afslutning</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Pris:</strong> ekskl. moms kr. 3.900,-&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Tilmelding:</strong> <span style=\"color: #0000ff;\"><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #0000ff;\">salg@cloudrouter.dk</span></a></span></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\">Vi byder velkommen fra kl. 08:00 med morgenkaffe og rundstykker til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag.</span></p>',	'Under træningen skal du udføre hand-on konfigurationer på køreklar Infinity controller og Access punkter.',	'',	'',	'',	0,	0),
(46,	'LigoWave Trådløs backbone hands-on workshop',	'2018-04-25',	'08:30:00',	'<p><span style=\"color: #333333;\">Under tr&aelig;ningen skal du udf&oslash;re hand-on konfigurationer p&aring; k&oslash;reklar DLB-ac, LigoPTP og LigoPTMP enheder.&nbsp;</span><a title=\"LigoWave DLB-ac, LigoPTP og LigoPTMP hands-on workshop\" href=\"https://drive.google.com/open?id=1gorKGP4b2uYvGwUY_eGONeQpaF5faTPH\" target=\"_blank\"><span style=\"color: #0000ff;\">Download PDF</span></a></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p>08:00 - Morgenbr&oslash;d<br />08:30 - Introduktion 802.11 TDMA tr&aring;dl&oslash;s kommunikation<br />09:00 - DLB ac punkt-til-multipunkt konfiguration<br />10:00 - DLB ac VLAN, QoS og bandwidth konfiguration<br />11:00 - DLB ac WNMS management og SNMP overv&aring;gning konfiguration</p>\r\n<p>11:30 - Frokost</p>\r\n<p>12:00 -&nbsp;LigoPTMP (Carrier-grade) punkt-til-multipunkt konfiguration<br />13:00 -&nbsp;LigoPTMP VLAN, QoS og bandwidth konfiguration<br />14:00 -&nbsp;LigoPTMP WNMS management og SNMP overv&aring;gning konfiguration<br />15:00 -&nbsp;LigoPTP (RapidFire) punkt-til-punkt konfiguration<br />16:00 - Gennemgang af LigoWaves LinkCalc applikation og support portal<br />16:30 - 802.11 TDMA Tr&aring;dl&oslash;s Backbone Best-practice for WTTx, WiFi og CCTV l&oslash;sninger<br />17:00 &ndash; Afslutning</p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Pris:</strong> ekskl. moms kr. 4.600,-&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Tilmelding:</strong> <span style=\"color: #0000ff;\"><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #0000ff;\">salg@cloudrouter.dk</span></a></span></span></p>\r\n<p>&nbsp;</p>\r\n<p><span style=\"color: #333333;\">Vi byder velkommen fra kl. 08:00 med morgenkaffe og rundstykker til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag.</span></p>',	'Under træningen skal du udføre hand-on konfigurationer på køreklar DLB-ac, LigoPTP og LigoPTMP enheder.',	'',	'',	'',	0,	0),
