(67,	'Infinity WiFi Certification Training',	'2019-03-04',	'09:00:00',	'<p><span style=\"color: #333333;\">LigoWave Infinity WiFi certificeringskursus.</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Agenda&nbsp;</strong></span></p>\r\n<p><span style=\"color: #333333;\">08:30 <span>&ndash;&nbsp;</span>Morgenbr&oslash;d og kaffe</span><br /><span style=\"color: #333333;\">09:00 <span>&ndash;&nbsp;</span>Introduktion til TCP/IP kommunikation</span><br /><span style=\"color: #333333;\">09:30 <span>&ndash;&nbsp;</span>Introduktion til 802.11 tr&aring;dl&oslash;s kommunikation </span><br /><span style=\"color: #333333;\">10:30 <span>&ndash; I</span>nfinity WiFi Stand-alone AP konfiguration</span><br /><span style=\"color: #333333;\">11:00 <span>&ndash;&nbsp;</span>Infinity Cloud management basis konfiguration</span><br /><span style=\"color: #333333;\">11:30 <span>&ndash;&nbsp;</span>Infinity Cloud management QoS, bandwidth og maps konfiguration</span></p>\r\n<p><span style=\"color: #333333;\">12:00 <span>&ndash;&nbsp;</span>Frokost &ndash;&nbsp;let traktement</span></p>\r\n<p><span style=\"color: #333333;\">12:30 <span>&ndash;&nbsp;</span>Infinity WiFi Mesh netv&aelig;rk konfiguration</span><br /><span style=\"color: #333333;\">13:00 <span>&ndash;&nbsp;</span>Infinity WiFi VLAN og WPA-2 enterprise konfiguration</span><br /><span style=\"color: #333333;\">13:30 <span>&ndash;&nbsp;</span>Infinity WiFi Hotspot med login-portal konfiguration</span><br /><span style=\"color: #333333;\">14:00 &ndash; Infinity WiFi Best-practice for indend&oslash;rs og udend&oslash;rs</span><br /><span style=\"color: #333333;\">15:00 &ndash; Online eksamen for Infinity WiFi certificering </span><br /><span style=\"color: #333333;\">16:00 &ndash; Afslutning</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\"><strong>Information</strong></span><br /><span style=\"color: #333333;\">Du bedes medbringe en Laptop computer med Ethernet indgang, WiFi, og Chrome eller Firefox browser. Der vil v&aelig;re 2 x 230v str&oslash;mstik, 1 x Ethernet og WiFi netv&aelig;rksadgang pr. deltager i lokalet.</span></p>\r\n<p><span style=\"color: #333333;\">&nbsp;</span></p>\r\n<p><span style=\"color: #333333;\">Vi byder velkommen fra kl. 08:30 med morgenkaffe og rundstykker til dem som &oslash;nsker at starte dagen i god tid. Der vil blive serveret sandwich og drikkevarer til middag.</span></p>\r\n<p><span style=\"color: #333333;\"><strong><br /></strong></span></p>\r\n<p><strong>Vejledende udsalgspris: ekskl. moms kr. 3.800,-&nbsp;</strong></p>\r\n<p><span><strong>Kontakt Christine Foged Knudsen </strong></span><span style=\"color: #0000ff;\"><span><span style=\"color: #000000;\"><strong><span>p&aring;</span>&nbsp;</strong></span></span></span><span style=\"color: #0000ff;\"><strong><a href=\"mailto:salg@cloudrouter.dk\"><span style=\"color: #0000ff;\">salg@cloudrouter.dk</span></a></strong><span style=\"color: #000000;\"><strong>&nbsp;</strong></span><strong><strong><span style=\"color: #000000;\">for tilmelding.</span></strong></strong></span></p>',	'LigoWave Infinity WiFi certificeringskursus',	'',	'http://www.cloudrouter.dk/docs/events/2018/Outdoor_sector_WiFi.png',	'',	0,	1),
